func (s NativeTypes) JSONSize() int {
	size := 342
	if s.Addr.Is4() {
		size += 15
	} else {
		size += 39
	}
	if z := len(s.Addr.Zone()); z > 0 {
		size += 1 + z*2
	}
	size += ((len(s.Blob) + 2) / 3) * 4
	size += len(s.ByteArray) * 4
	if s.Cidr.Addr().Is4() {
		size += 19
	} else {
		size += 43
	}
	size += len(s.HexBlob) * 2
	if s.LegacyIP.To4() != nil {
		size += 15
	} else if len(s.LegacyIP) != 0 {
		size += 39
	} else {
		size += 2
	}
	return size
}

func (s NativeTypes) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"addr\":\""...)
	dst = ggen.AppendNetipAddr(dst, s.Addr)
	dst = append(dst, ",\"blob\":"...)
	if s.Blob == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = base64.StdEncoding.AppendEncode(dst, s.Blob)
		dst = append(dst, '"')
	}
	dst = append(dst, ",\"byteArray\":"...)
	if s.ByteArray == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '[')
		for i, b := range s.ByteArray {
			if i > 0 {
				dst = append(dst, ',')
			}
			dst = strconv.AppendUint(dst, uint64(b), 10)
		}
		dst = append(dst, ']')
	}
	dst = append(dst, ",\"cidr\":\""...)
	if dst, err = s.Cidr.AppendText(dst); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"createdAt\":\""...)
	dst = s.CreatedAt.AppendFormat(dst, time.RFC3339Nano)
	dst = append(dst, "\",\"hexBlob\":"...)
	if s.HexBlob == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = hex.AppendEncode(dst, s.HexBlob)
		dst = append(dst, '"')
	}
	dst = append(dst, ",\"issuedAt\":\""...)
	dst = s.IssuedAt.AppendFormat(dst, time.RFC3339)
	dst = append(dst, "\",\"legacyIP\":\""...)
	if dst, err = s.LegacyIP.AppendText(dst); err != nil {
		return dst, err
	}
	dst = append(dst, "\",\"secDur\":"...)
	if dst, err = ggen.AppendFloat(dst, s.SecDur.Seconds(), 64); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"unitDur\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.UnitDur.String())
	dst = append(dst, ",\"unixAt\":"...)
	dst = ggen.AppendUnixSeconds(dst, s.UnixAt)
	return append(dst, '}'), nil
}

